"beam-stress-02":Object.freeze({absoluteTolerance:0.05,relativeTolerance:0,precision:4,assumptions:"Flexion simple d’une section rectangulaire homogène b = 40 mm et h = 80 mm ; moment fléchissant maximal ; formule σ = M/W.",solution:"W = bh²/6 = 40 × 80²/6 = 42 666,7 mm³. M = 800 N·m = 800 000 N·mm. σ = M/W = 18,75 N/mm² = 18,75 MPa. Comparer ensuite à une contrainte admissible justifiée."}),
